import{_ as o,o as a,c as t,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"Three-Tier Role-Based Dashboards, Workspace UX, Timezone Consistency & Duplicate Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/02-agency-studio-plans/role-based-dashboards-and-ux/spec.md","filePath":"feature/modules/02-agency-studio-plans/role-based-dashboards-and-ux/spec.md"}'),n={name:"feature/modules/02-agency-studio-plans/role-based-dashboards-and-ux/spec.md"};function i(s,e,d,r,l,p){return a(),t("div",null,[...e[0]||(e[0]=[c('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="three-tier-role-based-dashboards-workspace-ux-timezone-consistency-duplicate-workspace" tabindex="-1">Three-Tier Role-Based Dashboards, Workspace UX, Timezone Consistency &amp; Duplicate Workspace <a class="header-anchor" href="#three-tier-role-based-dashboards-workspace-ux-timezone-consistency-duplicate-workspace" aria-label="Permalink to &quot;Three-Tier Role-Based Dashboards, Workspace UX, Timezone Consistency &amp; Duplicate Workspace&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>role-based-dashboards-and-ux</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>02-agency-studio-plans</code> — Agency, Personal Studio, Dashboards &amp; Realtime Notifications</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Guest, Owner, Manager, Creator, Client, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>role-based-dashboards</code>, <code>dashboard-experience</code>, <code>agency-profile-presentation</code>, <code>agency-invitation-email-language</code>, <code>workspace-timezone-consistency</code>, <code>navigation-ux-linked-demo-data</code>, <code>landing-lab-replaced-apps</code>, <code>admin-ui-consistency</code>, <code>duplicate-workspace</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/03-agency-workspace/README.html">3.4 Agency &amp; Workspace</a> (<code>3.4.1–3.4.26</code>)</td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Unify BrandHub&#39;s cross-cutting navigation, <strong>3-tier Role-Based Dashboards</strong> (<code>Personal -&gt; Agency -&gt; Workspace</code> with <code>Overview</code> + <code>Analytics</code> tabs and Excel export), live Agency Profile &amp; localized (<code>vi</code>/<code>en</code>) invitation email previews, Workspace IANA timezone consistency, <strong>Duplicate Workspace</strong> (<code>DA-1255</code>), Landing &#39;17 Replaced Apps&#39; interactive showcase, and Admin UI design-system consistency.</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As an <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, or <code>Client</code>, I want a role-tailored Dashboard across Personal, Agency, and Workspace levels showing urgent items, approval bottlenecks, and real KPIs (<code>DashboardAnalyticsController</code>) with 1-click drill-down drawers.</li><li>As an <code>Owner</code>, I want to duplicate a proven Workspace blueprint (<code>POST /api/v1/workspaces/{workspaceId}/duplicate</code>), send Agency invitations in <code>vi</code> or <code>en</code>, and enforce consistent Workspace timezones on Content Request and Post deadlines.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Three-Tier Role-Based Dashboards (<code>role-based-dashboards</code>, <code>dashboard-experience</code>):</strong> <code>DashboardAnalyticsController</code> (<code>/api/v1/analytics/me</code>, <code>/agencies/{agencyId}</code>, <code>/workspaces/{workspaceId}</code> + <code>/overview</code>, <code>/items</code>, <code>/export.xlsx</code>) powers <code>Overview</code> (KPI strip, <code>AttentionStrip</code>, <code>NextUpCard</code>, <code>QuickActions</code>, inline <code>DetailDrawer</code>) and <code>Analytics</code> (<code>ComparisonTable</code>, <code>ScoreBadge</code>, multi-range charts) tailored per canonical role (<code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>).</li><li><strong>Agency Branding Live Preview &amp; Localized Invitations (<code>agency-profile-presentation</code>, <code>agency-invitation-email-language</code>):</strong> <code>AgencyCreateLivePreview.tsx</code> and <code>AgencyDetailLivePreview.tsx</code> mirror branding edits in real time; <code>POST /api/v1/agencies/{agencyId}/invitations</code> accepts recipient email language (<code>vi</code> | <code>en</code>) and renders localized HTML templates matching the live Agency profile.</li><li><strong>Workspace Timezone Consistency (<code>workspace-timezone-consistency</code>):</strong> Content Request deadlines, Task due dates, and Post schedules evaluate against <code>workspaces.timezone</code> (default <code>Asia/Ho_Chi_Minh</code>) across validation, persistence, and UI pickers (<code>TimezoneSelect.tsx</code>).</li><li><strong>Duplicate Workspace (<code>duplicate-workspace</code>, <code>DA-1255</code>):</strong> <code>GET /api/v1/workspaces/{workspaceId}/duplicate-options</code> and <code>POST /api/v1/workspaces/{workspaceId}/duplicate</code> allow <code>Owner</code> (within plan workspace quota) to clone folder hierarchy, hashtag collections, watermark presets, and optional internal member roles into a new Workspace without copying Client data or published posts.</li><li><strong>Landing Showcase &amp; Admin UI Consistency (<code>landing-lab-replaced-apps</code>, <code>admin-ui-consistency</code>, <code>navigation-ux-linked-demo-data</code>):</strong> Interactive landing showcase demonstrates how BrandHub replaces fragmented SaaS tools; Admin panels share standardized <code>AdminErrorBanner</code>, <code>AdminDateRangePicker</code>, typography, and linked demo seed integrity.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>dashboard.*</code>, <code>agency.invite.emailLanguage</code>, <code>workspace.duplicate.*</code>, <code>landing.replacedApps.*</code> in <code>src/i18n/locales/{vi,en}/*.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/dashboard/index.tsx</code>, <code>pages/agency/dashboard/index.tsx</code>, <code>pages/workspace/dashboard.tsx</code>, <code>components/dashboard/*</code>, <code>DuplicateWorkspaceDialog.tsx</code>, <code>AgencyDetailLivePreview.tsx</code>, <code>TimezoneSelect.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/dashboard/HomeDashboardScreen.tsx</code>, <code>DashboardScreen.tsx</code>, <code>src/services/dashboardAnalyticsService.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;">`GET /api/v1/analytics/me[/overview</td><td style="text-align:left;">/items] &amp; /agencies/{id}[/overview</td><td style="text-align:left;">/items</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/workspaces/{workspaceId}/duplicate-options &amp; POST /duplicate</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>WorkspaceController</code> -&gt; clones Workspace structure within subscription plan quota</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/agencies/{agencyId}/invitations</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>AgencyController</code> -&gt; dispatches <code>vi</code> or <code>en</code> localized invitation email</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Plan Quota Check on Duplicate Workspace:</strong> Rejects <code>POST /duplicate</code> (<code>403/409 PLAN_LIMIT_REACHED</code>) if Agency active workspace count already equals plan entitlement.</li><li><strong>Multi-Agency User Context:</strong> Personal tier (<code>/api/v1/analytics/me</code>) aggregates across all Agencies/Workspaces where the user is an active member without leaking sibling Workspaces.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/03-agency-workspace/README.html">3.4 Agency &amp; Workspace</a> (<code>3.4.1–3.4.26</code>)</li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/03-agency-workspace.html">BA 03 Agency &amp; Workspace</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul><h3 id="bo-đem-va-loi-vao-cong-viec-tren-web" tabindex="-1">Bộ đếm và lối vào công việc trên Web <a class="header-anchor" href="#bo-đem-va-loi-vao-cong-viec-tren-web" aria-label="Permalink to &quot;Bộ đếm và lối vào công việc trên Web&quot;">​</a></h3><p>Bảng điều khiển cá nhân, Agency và Workspace dùng số liệu tổng quan đã phân quyền. Nút cá nhân hiển thị số việc đang giữ, việc gấp, việc bị trả lại hoặc chờ người dùng duyệt theo dữ liệu có thể xử lý. Owner thấy việc quá hạn và chưa giao của Agency. Manager thấy các số tương ứng trong Workspace phụ trách. Mỗi nút và thẻ mở đúng danh sách chi tiết. Thanh bên hiển thị số việc gấp và chờ duyệt theo Workspace, hoặc số chờ duyệt ở lối vào Agency. Badge chỉ hiện khi có việc. Dùng khóa giao diện <code>dashboard.analytics.actions</code> và <code>dashboard.analytics.overviewKpi</code> song song VI/EN và màu theo theme sáng/tối.</p>',21)])])}const u=o(n,[["render",i]]);export{h as __pageData,u as default};
